    r['access']['data_urls'] += [u.replace('ftp://ftp.ncbi.nlm.nih.gov/','https://ftp.ncbi.nlm.nih.gov/') for u in geo[acc]['metadata'].get('Series_supplementary_file',[]) if u!='NONE']
